func PostgreSQLSchema(schema string) string {
	return strings.ReplaceAll(postgresSchema, `"business"`, `"`+strings.ReplaceAll(schema, `"`, `""`)+`"`)
}

func Definition(schema string) (oversync.SchemaGeneration, []oversync.RegisteredTable, error) {
	var definition struct {
		Generation oversync.SchemaGeneration
		Registered []oversync.RegisteredTable
	}
	if err := json.Unmarshal([]byte(definitionJSON), &definition); err != nil {
		return oversync.SchemaGeneration{}, nil, err
	}
	for i := range definition.Generation.Tables {
		t := &definition.Generation.Tables[i]
		t.Schema = schema
		for j := range t.ForeignKeys {
			t.ForeignKeys[j].ReferencedSchema = schema
		}
	}
	for i := range definition.Registered {
		definition.Registered[i].Schema = schema
	}
	return definition.Generation, definition.Registered, nil
}

